    def share_face(c1, c2):
        x1, y1, z1, x2, y2, z2 = c1
        x3, y3, z3, x4, y4, z4 = c2

        # Check if they touch on a face (area > 0)
        # They must coincide on one dimension's boundary and overlap in the other two dimensions

        # Face perpendicular to x-axis
        if x2 == x3 or x4 == x1:
            if max(y1, y3) < min(y2, y4) and max(z1, z3) < min(z2, z4):
                return True
        # Face perpendicular to y-axis
        if y2 == y3 or y4 == y1:
            if max(x1, x3) < min(x2, x4) and max(z1, z3) < min(z2, z4):
                return True
        # Face perpendicular to z-axis
        if z2 == z3 or z4 == z1:
            if max(x1, x3) < min(x2, x4) and max(y1, y3) < min(y2, y4):
                return True
        return False

    result = []
