import sys
from itertools import combinations

def find_parent(parent, x):
    if parent[x] != x:
        parent[x] = find_parent(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    px, py = find_parent(parent, x), find_parent(parent, y)
    if px == py:
        return False
    if rank[px] < rank[py]:
        px, py = py, px
    parent[py] = px
    if rank[px] == rank[py]:
        rank[px] += 1
    return True

def is_spanning_tree(edges, n):
    parent = list(range(n + 1))
    rank = [0] * (n + 1)
    count = 0
    for u, v, _ in edges:
        if union(parent, rank, u, v):
            count += 1
    return count == n - 1

def solve():
    data = sys.stdin.read().split()
    n = int(data[0]); m = int(data[1]); k = int(data[2])
    edges = []
    index = 3
    for _ in range(m):
        u = int(data[index]); v = int(data[index+1]); w = int(data[index+2])
        index += 3
        edges.append((u, v, w))

    min_cost = float('inf')
    for comb in combinations(edges, n - 1):
        if is_spanning_tree(comb, n):
            total_weight = sum(w for _, _, w in comb)
            cost = total_weight % k
            if cost < min_cost:
                min_cost = cost
    print(min_cost)

solve()
```

