def solve():
    sys.setrecursionlimit(1 << 25)
    N, M = map(int, sys.stdin.readline().split())
    edges = []
    parent = list(range(N+1))

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        u_root = find(u)
        v_root = find(v)
        if u_root != v_root:
            parent[v_root] = u_root

    for _ in range(M):
        K, C = map(int, sys.stdin.readline().split())
        vertices = list(map(int, sys.stdin.readline().split()))
        for i in range(K):
            for j in range(i+1, K):
                u, v = vertices[i], vertices[j]
                edges.append((C, u, v))
                union(u, v)

    root = find(1)
    connected = all(find(i) == root for i in range(2, N+1))

    if not connected:
        print(-1)
    else:
        edges.sort()
        total = 0
        parent = list(range(N+1))
        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]
                u = parent[u]
            return u

        for C, u, v in edges:
            if find(u) != find(v):
                union(u, v)
                total += C
