def numberOfSequence(n, sick):
    MOD = 10**9 + 7
    uninfected = []
    start = 0
    for s in sick:
        if s - start > 0:
            uninfected.append(s - start)
        start = s + 1
    if start < n:
        uninfected.append(n - start)

    total_ways = 1
    total_uninfected = sum(uninfected)
    fact = [1] * (total_uninfected + 1)
    for i in range(1, total_uninfected + 1):
        fact[i] = fact[i-1] * i % MOD

    inv_fact = [1] * (total_uninfected + 1)
    inv_fact[total_uninfected] = pow(fact[total_uninfected], MOD-2, MOD)
    for i in range(total_uninfected, 0, -1):
        inv_fact[i-1] = inv_fact[i] * i % MOD

    def comb(n, r):
        if r > n or r < 0:
            return 0
        return fact[n] * inv_fact[r] % MOD * inv_fact[n-r] % MOD

    for i, u in enumerate(uninfected):
        if u == 0:
            continue
        ways = comb(total_uninfected, u)
        if i != 0 and i != len(uninfected) - 1:
            ways = ways * pow(2, u - 1, MOD) % MOD
        total_ways = total_ways * ways % MOD
        total_uninfected -= u

    return total_ways
