import sys
MOD = 998244353

def solve():
    H, W = map(int, sys.stdin.readline().split())
    grid = [list(sys.stdin.readline().strip()) for _ in range(H)]

    def count_components():
        visited = [[False]*W for _ in range(H)]
        cnt = 0
        for i in range(H):
            for j in range(W):
                if grid[i][j] == '#' and not visited[i][j]:
                    cnt += 1
                    stack = [(i, j)]
                    visited[i][j] = True
                    while stack:
                        x, y = stack.pop()
                        for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                            nx, ny = x+dx, y+dy
                            if 0<=nx<H and 0<=ny<W and grid[nx][ny]=='#' and not visited[nx][ny]:
                                visited[nx][ny] = True
                                stack.append((nx, ny))
        return cnt

    red_cells = []
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.':
                red_cells.append((i, j))

    total = 0
    for i, j in red_cells:
        grid[i][j] = '#'
        total += count_components()
        grid[i][j] = '.'

    print(total // len(red_cells) % MOD)

solve()
