import sys
from collections import defaultdict
import heapq

def main():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])

    edges = []
    graph = defaultdict(list)

    index = 2
    for _ in range(m):
        u = int(data[index])
        v = int(data[index + 1])
        w = int(data[index + 2])
        index += 3
        edges.append((u, v, w))
        graph[u].append((v, w))

    # Floyd-Warshall to compute shortest paths between all pairs
    INF = float('inf')
    dist = [[INF] * (n + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        dist[i][i] = 0

    for u, v, w in edges:
        dist[u][v] = min(dist[u][v], w)

    for k in range(1, n + 1):
        for i in range(1, n + 1):
            for j in range(1, n + 1):
                if dist[i][k] != INF and dist[k][j] != INF:
                    dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

    # Check connectivity: every pair must be reachable
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if dist[i][j] == INF:
                print("No")
                return

    # TSP-like DP over subsets
    dp = [defaultdict(lambda: INF) for _ in range(1 << n)]

    for start in range(1, n + 1):
        dp[1 << (start - 1)][start] = 0

    for mask in range(1 << n):
        for u in range(1, n + 1):
            if dp[mask][u] == INF:
                continue
            for v in range(1, n + 1):
                if u == v:
                    continue
                if dist[u][v] == INF:
                    continue
                new_mask = mask | (1 << (v - 1))
                new_cost = dp[mask][u] + dist[u][v]
                if new_cost < dp[new_mask][v]:
                    dp[new_mask][v] = new_cost

    full_mask = (1 << n) - 1
    result = min(dp[full_mask][i] for i in range(1, n + 1))

    if result == INF:
        print("No")
    else:
        print(result)

main()
