def maximumEnergy(energy: list[int], k: int) -> int:
    n = len(energy)
    dp = [0] * n
    for i in range(n - 1, -1, -1):
        dp[i] = energy[i] + (dp[i + k] if i + k < n else 0)
    return max(dp)
