def countServersWithoutRequests(n, logs, x, queries):
    logs.sort(key=lambda log: log[1])
    sorted_queries = sorted([(queries[i], i) for i in range(len(queries))])

    result = [0] * len(queries)
    active_servers = {}
    left = 0

    for query_time, original_idx in sorted_queries:
        start_time = query_time - x

        while left < len(logs) and logs[left][1] < start_time:
            server_id = logs[left][0]
            if server_id in active_servers:
                active_servers[server_id] -= 1
                if active_servers[server_id] == 0:
                    del active_servers[server_id]
            left += 1

        while left < len(logs) and logs[left][1] <= query_time:
            server_id = logs[left][0]
            active_servers[server_id] = active_servers.get(server_id, 0) + 1
            left += 1

        result[original_idx] = n - len(active_servers)

        # Roll back the right pointer for next iteration
        while left > 0 and (left >= len(logs) or logs[left-1][1] > query_time):
            left -= 1

    return result
