    for i in range(H+2, H+2+N):
        r, c, e = map(int, data[i].split())
        medicines[(r-1, c-1)] = e

    start = None
    goal = None
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'T':
                goal = (i, j)

    queue = deque([(start[0], start[1], 0)])  # (row, col, energy)
    visited = set()
    visited.add((start[0], start[1], 0))

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    while queue:
        r, c, energy = queue.popleft()

        if (r, c) == goal:
