def constructProductMatrix(grid):
    MOD = 12345
    n, m = len(grid), len(grid[0])
    total_product = 1
    zero_count = 0

    for i in range(n):
        for j in range(m):
            if grid[i][j] % MOD != 0:
                total_product = (total_product * grid[i][j]) % MOD
            else:
                zero_count += 1

    result = [[0] * m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            if zero_count > 1:
                result[i][j] = 0
            elif zero_count == 1:
                if grid[i][j] % MOD == 0:
                    result[i][j] = total_product
                else:
                    result[i][j] = 0
            else:
