    for a in A:
        total_outcomes = (total_outcomes * a) % MOD

    # dp[mask][s] = number of ways to achieve sum s using subset of dice (up to current)
    # Instead, we use recursion with memoization over index and current sum
    @lru_cache(maxsize=None)
    def count_ways(i, current_sum):
        if current_sum == 10:
            return 1
        if i == N or current_sum > 10:
            return 0

        res = 0
        # Skip die i
        res += count_ways(i + 1, current_sum)
        # Use die i: try all faces from 1 to A[i]
        for face in range(1, A[i] + 1):
            new_sum = current_sum + face
            if new_sum <= 10:
                res += count_ways(i + 1, new_sum)
            else:
                break
        return res % MOD

    good_outcomes = count_ways(0, 0)
    prob = (good_outcomes * modinv(total_outcomes)) % MOD
    print(prob)

