import sys
from functools import lru_cache

MOD = 998244353

def main():
    S = sys.stdin.readline().strip()
    n = len(S)

    @lru_cache(maxsize=None)
    def dp(pos, state):
        # state: 0 -> nothing matched
        # state: 1 -> matched first char (uppercase)
        # state: 2 -> matched first two same uppercase
        # state: 3 -> matched first two uppercase and one lowercase (third)
        # state: 4 -> matched full DDoS pattern (forbidden)
        if state == 4:
            return 0
        if pos == n:
            return 1

        total = 0
        chars = []
        if S[pos] != '?':
            chars = [S[pos]]
        else:
            for c in range(26):
                chars.append(chr(ord('A') + c))
                chars.append(chr(ord('a') + c))

        for c in chars:
            new_state = state
            if state == 0:
                if 'A' <= c <= 'Z':
                    new_state = 1
            elif state == 1:
                if 'A' <= c <= 'Z' and c == S[pos-1] if S[pos-1] != '?' else True:
                    # We need to track what the first char was - this approach won't work
                    # Need to reframe state to not depend on specific characters
                    pass
            # This approach is flawed because we need to track the actual character

        # Redesigning approach
        return 0

    # Correct approach with different state representation
    @lru_cache(maxsize=None)
    def dp2(pos, first_char, matched_count):
        # matched_count: 0=none, 1=first char, 2=first two same, 3=first two same + lowercase, 4=complete
        # first_char: None or the character (if matched_count >= 1)
        if matched_count == 4:
            return 0
        if pos == n:
            return 1

        total = 0
        chars = []
        if S[pos] != '?':
            chars = [S[pos]]
        else:
            for i in range(26):
                chars.append(chr(ord('A') + i))
                chars.append(chr(ord('a') + i))

        for c in chars:
            new_matched = matched_count
            new_first = first_char

            if matched_count == 0:
                if 'A' <= c <= 'Z':
                    new_matched = 1
                    new_first = c
            elif matched_count == 1:
                if 'A' <= c <= 'Z' and c == new_first:
                    new_matched = 2
                elif 'a' <= c <= 'z':
                    new_matched = 0  # Can't form pattern, but could start over later
                    # Actually, we might still have the first char as c if it's uppercase, but it's not
            elif matched_count == 2:
                if 'a' <= c <= 'z':
                    new_matched = 3
                elif 'A' <= c <= 'Z':
                    if c == new_first:
                        new_matched = 2  # Still have first two
                    else:
                        new_matched = 1  # New first char
                        new_first = c
                else:
                    new_matched = 0
            elif matched_count == 3:
                if 'A' <= c <= 'Z' and c == new_first:
                    new_matched = 4  # Found complete pattern
                elif 'A' <= c <= 'Z':
                    new_matched = 1
                    new_first = c
                elif 'a' <= c <= 'z':
                    new_matched = 0

            total = (total + dp2(pos + 1, new_first, new_matched)) % MOD

        return total % MOD

    # Even better approach: since we only care about avoiding the pattern,
    # we can use DP states that don't track the specific character but use
    # the fact that we only need to know when we have matches
    @lru_cache(maxsize=None)
    def dp3(pos, state, first_ch):
        # state 0: no match
        # state 1: have first uppercase
        # state 2: have two consecutive same uppercase
        # state 3: have two same uppercase followed by lowercase
        # first_ch: the required character for matching, or -1 if none
        if state == 3:
            # We're waiting for final uppercase to complete pattern
            # If next char is uppercase and equals first_ch, then we get forbidden pattern
            pass
        if pos == n:
            return 1

        total = 0
        options = []
        if S[pos] != '?':
            options = [S[pos]]
        else:
            for i in range(26):
                options.append(chr(ord('A') + i))
                options.append(chr(ord('a') + i))

        for c in options:
            ns = state
            fc = first_ch
            valid = True

            if state == 0:
                if 'A' <= c <= 'Z':
                    ns = 1
                    fc = c
            elif state == 1:
                if 'A' <= c <= 'Z':
                    if c == fc:
                        ns = 2
                    else:
                        ns = 1
                        fc = c
                elif 'a' <= c <= 'z':
                    ns = 0
            elif state == 2:
                if 'a' <= c <= 'z':
                    ns = 3
                elif 'A' <= c <= 'Z':
                    if c == fc:
                        ns = 2
                    else:
                        ns = 1
                        fc = c
            elif state == 3:
                if 'A' <= c <= 'Z':
                    if c == fc:
                        valid = False  # This would create the forbidden pattern
                    else:
                        ns = 1
                        fc = c
                elif 'a' <= c <= 'z':
                    ns = 0

            if valid:
                total = (total + dp3(pos + 1, ns, fc)) % MOD

        return total % MOD

    result = dp3(0, 0, -1)
    print(result)

main()
