MOD = 10**9 + 7

def count_sub_multisets(nums, l, r):
    from collections import defaultdict
    freq = defaultdict(int)
    for num in nums:
        freq[num] += 1

    max_sum = sum(num * freq[num] for num in freq)
    dp = [0] * (max_sum + 1)
    dp[0] = 1

    for num, count in freq.items():
        for j in range(max_sum, num - 1, -1):
            for k in range(1, count + 1):
                if j - k * num >= 0:
                    dp[j] = (dp[j] + dp[j - k * num]) % MOD

    return sum(dp[l:r + 1]) % MOD
