def maximumStrength(nums, k):
    n = len(nums)
    dp = [[[-float('inf')] * 2 for _ in range(k + 1)] for __ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0][0] = 0

    for i in range(1, n + 1):
        for j in range(1, min(i, k) + 1):
            sign = 1 if j % 2 == 1 else -1
            multiplier = k - j + 1
            # Not taking nums[i-1] in any subarray
            dp[i][j][0] = max(dp[i-1][j][0], dp[i-1][j][1])
            # Taking nums[i-1] in the j-th subarray
            dp[i][j][1] = max(dp[i-1][j][1], dp[i-1][j-1][0], dp[i-1][j-1][1]) + sign * nums[i-1] * multiplier

    return max(dp[n][k][0], dp[n][k][1])
