def canMakeSubarrayZero(nums, k):
    n = len(nums)
    diff = [0] * (n + 1)

    for i in range(n):
        if i > 0:
            diff[i] += diff[i - 1]
        if diff[i] > nums[i]:
            return False
        ops_needed = nums[i] - diff[i]
        if ops_needed < 0:
            return False
        diff[i] += ops_needed
        if i + k <= n:
            diff[i + k] -= ops_needed
        else:
            if ops_needed > 0:
                return False

    return diff[n] == 0
