def minOperations(nums, k):
    nums.sort()
    n = len(nums)
    median_idx = (n - 1) // 2
    median = nums[median_idx]

    operations = 0
    if median < k:
        for i in range(median_idx, n):
            if nums[i] < k:
                operations += k - nums[i]
    else:
        for i in range(median_idx + 1):
            if nums[i] > k:
                operations += nums[i] - k
    return operations
