def numberOfStableArrays(zero: int, one: int, limit: int) -> int:
    MOD = 10**9 + 7
    dp = [[[0] * (limit + 1) for _ in range(limit + 1)] for __ in range(2)]
    dp[0][0][0] = 1

    for i in range(zero + one + 1):
        new_dp = [[[0] * (limit + 1) for _ in range(limit + 1)] for __ in range(2)]
        for z in range(min(i, zero) + 1):
            o = i - z
            if o > one:
                continue
            for lz in range(limit + 1):
                for lo in range(limit + 1):
                    val = dp[z % 2][lz][lo]
                    if val == 0:
                        continue
                    if z < zero and lz < limit:
                        new_dp[(z+1)%2][lz+1][0] = (new_dp[(z+1)%2][lz+1][0] + val) % MOD
                    if o < one and lo < limit:
                        new_dp[z%2][0][lo+1] = (new_dp[z%2][0][lo+1] + val) % MOD
        dp = new_dp

    result = 0
