import sys
from collections import deque
from itertools import permutations

def main():
    input = sys.stdin.read
    data = input().splitlines()

    H, W, T = map(int, data[0].split())
    grid = [line.strip() for line in data[1:H+1]]

    start = None
    goal = None
    candies = []

    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'G':
                goal = (i, j)
            elif grid[i][j] == 'o':
                candies.append((i, j))

    def bfs_distance(start_pos, end_pos):
        if start_pos == end_pos:
            return 0
        queue = deque([(start_pos[0], start_pos[1], 0)])
        visited = [[False] * W for _ in range(H)]
        visited[start_pos[0]][start_pos[1]] = True

        while queue:
            x, y, dist = queue.popleft()
            for dx, dy in [(0,1), (0,-1), (1,0), (-1,0)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < H and 0 <= ny < W and not visited[nx][ny] and grid[nx][ny] != '#':
                    if (nx, ny) == end_pos:
                        return dist + 1
                    visited[nx][ny] = True
                    queue.append((nx, ny, dist + 1))
        return float('inf')

    # Get distances between important points
    points = [start] + candies + [goal]
    n = len(points)
    dist_matrix = [[float('inf')] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            dist_matrix[i][j] = bfs_distance(points[i], points[j])

    # If start to goal distance exceeds T, impossible
    if dist_matrix[0][-1] > T:
        print(-1)
        return

    # No candies case
    if not candies:
        print(0)
        return

    # Traveling salesman-like problem on candies
    num_candies = len(candies)
    max_candies = 0

    # Try all subsets of candies in descending order of size
    for k in range(num_candies, -1, -1):
        found = False
        for perm in permutations(range(1, num_candies + 1), k):
            total_dist = dist_matrix[0][perm[0]] if k > 0 else dist_matrix[0][-1]

            for i in range(k - 1):
                total_dist += dist_matrix[perm[i]][perm[i+1]]

            if k > 0:
                total_dist += dist_matrix[perm[-1]][-1]

            if total_dist <= T:
                max_candies = k
                found = True
                break

        if found:
            break

    print(max_candies)

main()
