def maxPalindromes(words):
    total_chars = {}
    for word in words:
        for c in word:
            total_chars[c] = total_chars.get(c, 0) + 1

    pairs = 0
    singles = 0
    for count in total_chars.values():
        pairs += count // 2
        singles += count % 2

    lengths = sorted([len(word) for word in words])
    result = 0
    for length in lengths:
        needed_pairs = length // 2
        if pairs >= needed_pairs:
            pairs -= needed_pairs
            if length % 2 == 1:
                if singles > 0:
                    singles -= 1
                else:
                    # Use one pair to create two singles, break one pair
                    if pairs > 0:
                        pairs -= 1
                        singles += 1
                        singles -= 1
                    else:
                        continue
            result += 1
        else:
            break
    return result
