def countCompleteSubstrings(word: str, k: int) -> int:
    def check(s, k):
        if len(s) % k != 0:
            return False
        max_unique = len(s) // k
        if max_unique == 0:
            return False

        for unique_count in range(1, min(max_unique + 1, 27)):
            length = unique_count * k
            if length > len(s):
                continue
            freq = {}
            for i in range(len(s)):
                if i >= length:
                    left_char = s[i - length]
                    freq[left_char] -= 1
                    if freq[left_char] == 0:
                        del freq[left_char]
                char = s[i]
                freq[char] = freq.get(char, 0) + 1

                if i >= length - 1:
                    valid = True
                    for count in freq.values():
                        if count != k:
                            valid = False
                            break
                    if valid and len(freq) == unique_count:
                        # Check adjacent difference condition for this substring
                        sub = s[i - length + 1:i + 1]
                        adj_ok = True
                        for j in range(1, len(sub)):
                            if abs(ord(sub[j]) - ord(sub[j-1])) > 2:
                                adj_ok = False
                                break
                        if adj_ok:
                            return True
        return False

    n = len(word)
    count = 0

    # Split by invalid adjacent differences
    start = 0
    for end in range(n):
        if end > 0 and abs(ord(word[end]) - ord(word[end-1])) > 2:
            # Process segment from start to end-1
            segment = word[start:end]
            seg_len = len(segment)
            for i in range(seg_len):
                for j in range(i + k, seg_len + 1):
                    if (j - i) % k == 0 and (j - i) // k <= 26:
                        if check(segment[i:j], k):
                            count += 1
            start = end

    # Process last segment
    segment = word[start:]
    seg_len = len(segment)
    for i in range(seg_len):
        for j in range(i + k, seg_len + 1):
            if (j - i) % k == 0 and (j - i) // k <= 26:
                if check(segment[i:j], k):
                    count += 1

    return count
