def minimumMoves(nums, k, maxChanges):
    n = len(nums)
    ones = [i for i in range(n) if nums[i] == 1]
    total_ones = len(ones)

    if total_ones >= k:
        res = float('inf')
        for center in range(n):
            collected = 0
            moves = 0
            if nums[center] == 1:
                collected += 1

            left = []
            right = []
            for pos in ones:
                if pos < center:
                    left.append(center - pos)
                elif pos > center:
                    right.append(pos - center)

            left.sort()
            right.sort()

            temp_moves = 0
            temp_collected = collected
            for dist in left + right:
                if temp_collected < k:
                    temp_moves += dist
                    temp_collected += 1
                else:
                    break
            if temp_collected == k:
                res = min(res, temp_moves)
        return res

    needed = k - total_ones
    base_moves = 0
    for i in range(n):
        if nums[i] == 1:
            base_moves += abs(i - 0)

    additional_moves = 0
    remaining_needed = needed
    changes_used = 0

    for i in range(n):
        if nums[i] == 0 and changes_used < maxChanges:
            dist = abs(i - 0)
            additional_moves += dist * 2  
            changes_used += 1
            remaining_needed -= 1
            if remaining_needed == 0:
                break

    if remaining_needed > 0:
        additional_moves += remaining_needed * 2

    return base_moves + additional_moves
