def canSortArray(nums):
    def count_set_bits(n):
        return bin(n).count('1')

    n = len(nums)
    bits = [count_set_bits(num) for num in nums]

    i = 0
    while i < n:
        j = i
        while j + 1 < n and bits[j + 1] == bits[i]:
            j += 1
        nums[i:j+1] = sorted(nums[i:j+1])
        i = j + 1

    return nums == sorted(nums)
