def minOperations(x: int, y: int) -> int:
    if x == y:
        return 0

    from collections import deque
    queue = deque([(x, 0)])
    visited = set()
    visited.add(x)

    while queue:
        curr, ops = queue.popleft()

        if curr == y:
            return ops

        # Apply all possible operations
        next_vals = []
        if curr % 11 == 0:
            next_vals.append(curr // 11)
        if curr % 5 == 0:
            next_vals.append(curr // 5)
        next_vals.append(curr - 1)
        next_vals.append(curr + 1)

        for nxt in next_vals:
            if nxt > 0 and nxt not in visited:
                visited.add(nxt)
                queue.append((nxt, ops + 1))
