def canSplitArray(nums, m):
    n = len(nums)
    if n <= 2:
        return True

    prefix_sum = [0]
    for num in nums:
        prefix_sum.append(prefix_sum[-1] + num)

    def can_split(l, r):
        if l >= r:
            return True
        total = prefix_sum[r + 1] - prefix_sum[l]
        for i in range(l, r):
            left_len = i - l + 1
            right_len = r - i
            left_sum = prefix_sum[i + 1] - prefix_sum[l]
            right_sum = prefix_sum[r + 1] - prefix_sum[i + 1]
            left_ok = (left_len == 1) or (left_sum >= m)
            right_ok = (right_len == 1) or (right_sum >= m)
            if left_ok and right_ok and can_split(l, i) and can_split(i + 1, r):
                return True
        return False

    return can_split(0, n - 1)
