def minOperations(nums, target):
    if sum(nums) < target:
        return -1

    import heapq
    heapq.heapify(nums)
    operations = 0

    while target > 0:
        if not nums:
            return -1

        num = -heapq.heappop(nums)
        if num <= target:
            target -= num
        else:
            operations += 1
            heapq.heappush(nums, -num // 2)
            heapq.heappush(nums, -num // 2)

