def canTraverseAllPairs(nums):
    if len(nums) == 1:
        return True
    if 1 in nums:
        return False

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            if rank[rx] < rank[ry]:
                parent[rx] = ry
            elif rank[rx] > rank[ry]:
                parent[ry] = rx
            else:
                parent[ry] = rx
                rank[rx] += 1

    n = len(nums)
    parent = list(range(n))
    rank = [0] * n

    factor_to_index = {}

    for i, num in enumerate(nums):
        d = 2
        while d * d <= num:
            if num % d == 0:
                if d in factor_to_index:
                    union(i, factor_to_index[d])
                else:
                    factor_to_index[d] = i
                while num % d == 0:
                    num //= d
            d += 1
        if num > 1:
            if num in factor_to_index:
                union(i, factor_to_index[num])
            else:
                factor_to_index[num] = i

    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return False
    return True
