def solve(queries):
    def get_powerful_array(x):
        arr = []
        power = 1
        while x:
            if x & 1:
                arr.append(power)
            x >>= 1
            power <<= 1
        return arr

    def get_value_at_index(idx):
        num = 1
        while idx >= len(get_powerful_array(num)):
            idx -= len(get_powerful_array(num))
            num += 1
        return get_powerful_array(num)[idx]

    result = []
    for start, end, mod in queries:
        product = 1
        for i in range(start, end + 1):
            product = (product * get_value_at_index(i)) % mod
        result.append(product)
    return result
