def specialPerm(nums):
    MOD = 10**9 + 7
    n = len(nums)
    graph = [[False] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if i != j and (nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0):
                graph[i][j] = True

    memo = {}

    def dp(mask, last):
        if mask == (1 << n) - 1:
            return 1
        if (mask, last) in memo:
            return memo[(mask, last)]

        result = 0
        for i in range(n):
            if not (mask & (1 << i)) and (last == -1 or graph[last][i]):
                result = (result + dp(mask | (1 << i), i)) % MOD

        memo[(mask, last)] = result
        return result

    return dp(0, -1)
```

