def maxPartitionsAfterOperations(s: str, k: int) -> int:
    n = len(s)
    if k == 1:
        res = 0
        i = 0
        while i < n:
            j = i
            seen = set()
            changed = False
            while j < n:
                if s[j] in seen:
                    j += 1
                elif len(seen) < 1:
                    seen.add(s[j])
                    j += 1
                else:
                    if not changed and j + 1 < n and s[j + 1] != s[i]:
                        changed = True
                        # simulate changing s[j] to break early
                        j += 1
                    else:
                        break
            res += 1
            i = j
        return res

    def count_partitions(t):
        cnt = 0
        i = 0
        while i < len(t):
            seen = set()
            j = i
            while j < len(t) and (len(seen) < k or t[j] in seen):
                seen.add(t[j])
                j += 1
            cnt += 1
            i = j
        return cnt

    best = 0
    for i in range(n):
        orig = s[i]
        for c in 'abcdefghijklmnopqrstuvwxyz':
            if c == orig:
                continue
            new_s = s[:i] + c + s[i+1:]
            best = max(best, count_partitions(new_s))

    # Also consider no change
    best = max(best, count_partitions(s))
    return best
