def minGroupsForValidAssignment(nums: list[int]) -> int:
    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1

    sizes = sorted(counts.values())

    def check(k):
        groups = 0
        for size in sizes:
            num_groups = (size + k) // (k + 1)
            rem = size - num_groups * k
            if rem < 0:
                return False
            groups += num_groups
        return True


    l, r = 1, len(nums)
    ans = len(nums)
    while l <= r:
        mid = (l + r) // 2
        if check(mid):
            ans = mid
            r = mid - 1
        else:
            l = mid + 1

    groups = 0
    for size in sizes:
        groups += (size + ans) // (ans + 1)

    return groups
