def maximumSubarraySum(nums, k):
    n = len(nums)
    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + nums[i]

    val_to_min_prefix = {}
    max_sum = float('-inf')

    for i in range(n):
        target1 = nums[i] - k
        target2 = nums[i] + k

        if target1 in val_to_min_prefix:
            j = val_to_min_prefix[target1]
            current_sum = prefix_sum[i + 1] - prefix_sum[j]
            max_sum = max(max_sum, current_sum)

        if target2 in val_to_min_prefix:
            j = val_to_min_prefix[target2]
            current_sum = prefix_sum[i + 1] - prefix_sum[j]
            max_sum = max(max_sum, current_sum)

        if nums[i] not in val_to_min_prefix or prefix_sum[i] < val_to_min_prefix[nums[i]]:
            val_to_min_prefix[nums[i]] = i

