        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    edges.sort(key=lambda x: x[2])

    mst_weight = 0
    mst_edges = 0

    for u, v, weight in edges:
        if union(u, v):
            mst_weight += weight
            mst_edges += 1

    if mst_edges != n - 1:
