def count_ways(n: int, x: int) -> int:
    MOD = 10**9 + 7

    def solve(remaining_n: int, current_num: int) -> int:
        if remaining_n == 0:
            return 1
        if remaining_n < 0:
            return 0

        power_of_num = current_num ** x
        if power_of_num > n:
            return 0

        take_num = solve(remaining_n - power_of_num, current_num + 1) % MOD
        skip_num = solve(remaining_n, current_num + 1) % MOD

        return (take_num + skip_num) % MOD

    return solve(n, 1)
