        for remainder in range(num):
            total_count = 0
            for j in range(remainder, r + 1, num):
                total_count = (total_count + dp[j]) % MOD
                if j >= num * (count + 1):
                    total_count = (total_count - dp[j - num * (count + 1)]) % MOD
                new_dp[j] = (new_dp[j] + total_count - dp[j]) % MOD
        dp = new_dp

