def can_traverse_all_pairs(nums):
    from collections import defaultdict

    prime_factors = defaultdict(set)
    for num in nums:
        temp = num
        for p in range(2, int(temp**0.5) + 1):
            if temp % p == 0:
                prime_factors[num].add(p)
                while temp % p == 0:
                    temp //= p
        if temp > 1:
            prime_factors[num].add(temp)

    connected_components = set()
    visited = set()

    def dfs(node):
        stack = [node]
        while stack:
            current = stack.pop()
            if current not in visited:
                visited.add(current)
                for num in prime_factors:
                    if num in prime_factors[current] and num not in visited:
                        stack.append(num)

    for num in prime_factors:
        if num not in visited:
            dfs(num)
            connected_components.add(frozenset(visited))

    return len(connected_components) == 1
