from collections import Counter

def minGroupsForValidAssignment(nums):
    freq = list(Counter(nums).values())
    total_indices = len(nums)

    def is_valid(groups):
        avg = total_indices // groups
        remainder = total_indices % groups
        small_size = avg
        large_size = avg + 1
        needed = (groups - remainder) * small_size + remainder * large_size
        if needed != total_indices:
            return False
        count_assignable = 0
        for f in freq:
            found = False
            for x in range(f + 1):
                y = f - x
                if x % small_size == 0 and y % large_size == 0 and x // small_size + y // large_size <= groups:
                    count_assignable += f
                    found = True
                    break
                if small_size == large_size:
                    break
            if not found:
                return False
        return True

    for k in range(1, total_indices + 1):
        if is_valid(k):
            return k
    return total_indices
