def min_operations_to_equal(s1, s2, s3):
    def can_equal(a, b, c):
        if len(a) < len(b) or len(a) < len(c):
            return False
        if a[:len(b)] != b or a[:len(c)] != c:
            return False
        return True

    if not can_equal(s1, s2, s3):
        return -1

    def get_min_operations(a, b, c):
        min_ops = float('inf')
        for l in range(min(len(a), len(b), len(c)), -1, -1):
            if a[:l] == b[:l] == c[:l]:
                ops = (len(a) - l) + (len(b) - l) + (len(c) - l)
                if ops < min_ops:
                    min_ops = ops
        return min_ops if min_ops != float('inf') else -1

    return get_min_operations(s1, s2, s3)
```

